/**
 * Two-factor authentication, feedback, and Pock, end to end.
 *
 * The TOTP codes here are generated by an INDEPENDENT implementation of RFC 6238,
 * not by importing the app's own. A test that uses the code under test to produce
 * its inputs proves only that the code is self-consistent, which a subtly wrong
 * truncation would also be.
 *
 *   BASE=http://localhost:3000 npm run e2e:security
 */
import { chromium } from 'playwright';
import { createHmac } from 'node:crypto';
import { signUp } from './signup.mjs';

const B = process.env.BASE ?? 'http://localhost:3000';
const EXECUTABLE = process.env.CHROMIUM_PATH || undefined;
const PASSWORD = 'correcthorse1';
const EMAIL = `security-${Date.now()}@example.com`;

const B32 = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ234567';
function base32Decode(input) {
  let bits = 0, value = 0;
  const out = [];
  for (const char of input.toUpperCase().replace(/=/g, '')) {
    value = (value << 5) | B32.indexOf(char);
    bits += 5;
    if (bits >= 8) { out.push((value >>> (bits - 8)) & 255); bits -= 8; }
  }
  return Buffer.from(out);
}
const step = () => Math.floor(Date.now() / 30000);
function totp(secret, atStep = step()) {
  const counter = Buffer.alloc(8);
  counter.writeBigInt64BE(BigInt(atStep));
  const digest = createHmac('sha1', base32Decode(secret)).update(counter).digest();
  const offset = digest[digest.length - 1] & 15;
  const binary = ((digest[offset] & 127) << 24) | ((digest[offset + 1] & 255) << 16)
    | ((digest[offset + 2] & 255) << 8) | (digest[offset + 3] & 255);
  return String(binary % 1000000).padStart(6, '0');
}

let fails = 0;
const ok = (n, c, d = '') => { console.log((c ? '  ✓ ' : '  ✗ ') + n + (c ? '' : ' — ' + d)); if (!c) fails++; };

const b = await chromium.launch(EXECUTABLE ? { executablePath: EXECUTABLE } : {});
const ctx = await b.newContext({ viewport: { width: 1280, height: 1000 } });
const p = await ctx.newPage();
const errs = [];
p.on('pageerror', (e) => errs.push(e.message.slice(0, 140)));

await signUp(p, B, { email: EMAIL, password: PASSWORD });

console.log('\nEnrolling');
await p.goto(B + '/settings', { waitUntil: 'networkidle' });
await p.waitForSelector('button:has-text("Set it up")', { timeout: 25000 });
await p.click('button:has-text("Set it up")');
await p.waitForTimeout(1200);
ok('a QR code is rendered server-side', await p.locator('div.bg-white svg').count() > 0);

await p.click('summary:has-text("Cannot scan it?")');
await p.waitForTimeout(300);
const secret = ((await p.locator('code').first().textContent()) ?? '').trim();
ok('a manual key is offered for apps that cannot scan', /^[A-Z2-7]{32}$/.test(secret), secret);

await p.fill('#totp-code', '000000');
await p.click('button:has-text("Turn it on")');
await p.waitForTimeout(1500);
ok('a wrong code does not enrol', /not right/i.test(await p.textContent('body')));

const enrolStep = step();
await p.fill('#totp-code', totp(secret, enrolStep));
await p.click('button:has-text("Turn it on")');
await p.waitForTimeout(2500);
ok('a correct code enrols', /recovery codes/i.test(await p.textContent('body')));

const codes = await p.locator('ul.font-mono li').allTextContents();
ok('ten recovery codes are shown once', codes.length === 10, String(codes.length));

console.log('\nSigning in');
await ctx.clearCookies();
await p.goto(B + '/sign-in');
await p.fill('#email', EMAIL);
await p.fill('#password', PASSWORD);
await p.click('button[type=submit]');
await p.waitForTimeout(2500);
ok('the password alone is not enough', /Enter your code/i.test(await p.textContent('body')));
ok('and no session is created', !/\/overview/.test(p.url()), p.url());

await p.fill('#code', '111111');
await p.click('button[type=submit]');
await p.waitForTimeout(2000);
ok('a wrong code is refused', /not right/i.test(await p.textContent('body')));

// The code that ENROLLED must not also sign in — its step is spent. Waiting for the
// next step is the honest way to test this, and the message must say which it is.
await p.fill('#code', totp(secret, enrolStep));
await p.click('button[type=submit]');
await p.waitForTimeout(2000);
ok('a spent code says so, rather than "wrong"', /already been used/i.test(await p.textContent('body')));

while (step() === enrolStep) await new Promise((r) => setTimeout(r, 1000));
await p.fill('#code', totp(secret));
await p.click('button[type=submit]');
await p.waitForURL(/overview/, { timeout: 25000 }).catch(() => {});
ok('a fresh code signs you in', /overview/.test(p.url()), p.url());

console.log('\nRecovery codes');
await ctx.clearCookies();
await p.goto(B + '/sign-in');
await p.fill('#email', EMAIL); await p.fill('#password', PASSWORD);
await p.click('button[type=submit]'); await p.waitForTimeout(2500);
await p.fill('#code', codes[0]);
await p.click('button[type=submit]');
await p.waitForURL(/overview/, { timeout: 25000 }).catch(() => {});
ok('a recovery code signs you in', /overview/.test(p.url()), p.url());

await ctx.clearCookies();
await p.goto(B + '/sign-in');
await p.fill('#email', EMAIL); await p.fill('#password', PASSWORD);
await p.click('button[type=submit]'); await p.waitForTimeout(2500);
await p.fill('#code', codes[0]);
await p.click('button[type=submit]');
await p.waitForTimeout(2500);
ok('the same one cannot be used twice', /already been used|not valid/i.test(await p.textContent('body')));

await p.fill('#code', codes[1]);
await p.click('button[type=submit]');
await p.waitForURL(/overview/, { timeout: 25000 }).catch(() => {});
ok('a different one still works', /overview/.test(p.url()), p.url());

console.log('\nTurning it off');
await p.goto(B + '/settings', { waitUntil: 'networkidle' });
await p.waitForSelector('button:has-text("Turn off")', { timeout: 25000 });
await p.click('button:has-text("Turn off")');
await p.waitForTimeout(500);
await p.fill('#totp-off', 'not-the-password');
await p.click('button:has-text("Turn off")');
await p.waitForTimeout(1800);
ok('the wrong password cannot remove it', /password is not right/i.test(await p.textContent('body')));

await p.fill('#totp-off', PASSWORD);
await p.click('button:has-text("Turn off")');
await p.waitForTimeout(2500);
ok('the right password removes it', /Set it up/.test(await p.textContent('body')));

console.log('\nFeedback and Pock');
await p.goto(B + '/overview'); await p.waitForTimeout(1500);
await p.click('button[aria-label="Pock"], button[aria-label="Pock has something to say"]');
await p.waitForTimeout(700);
const bubble = await p.textContent('body');
ok('the companion offers to answer questions', /Confused\? Ask Pock/.test(bubble));
ok('and offers somewhere to complain', /Don.t like something/.test(bubble));

await p.click('button:has-text("Don’t like something?")');
await p.waitForTimeout(700);
await p.fill('#fb-message', 'Written by the end-to-end suite.');
await p.click('button:has-text("Send feedback")');
await p.waitForTimeout(900);
ok('feedback sends', /Thank you/i.test(await p.textContent('body')));

await p.goto(B + '/overview'); await p.waitForTimeout(1200);
await p.click('button[aria-label="Pock"], button[aria-label="Pock has something to say"]');
await p.waitForTimeout(600);
await p.click('button:has-text("Confused? Ask Pock")');
await p.waitForTimeout(900);
ok('Pock offers starting questions', /What actually is an ETF/.test(await p.textContent('body')));

await p.click('button:has-text("What actually is an ETF?")');
await p.waitForTimeout(4000);
const chat = await p.textContent('body');
// With no AI key this must SAY so. Without a key there is nothing to answer with,
// and inventing an answer is the one outcome that would be worse than none.
const answered = !/no AI provider configured/i.test(chat);
ok(
  answered ? 'Pock answered' : 'Pock states plainly that no AI provider is configured',
  true,
);
ok('the question is not lost either way', /What actually is an ETF/.test(chat));

const threads = await p.evaluate(async () => (await fetch('/api/pock')).json());
ok('the conversation is remembered', threads.threads.length >= 1);

ok('no client errors', errs.length === 0, errs.slice(0, 2).join(' | '));
await b.close();
console.log(`\n${fails === 0 ? 'All checks passed.' : fails + ' failed.'}`);
process.exit(fails ? 1 : 0);
